setup:
CREATE TABLE lake_shores AS SELECT * FROM (VALUES
  ('Lake Arrow', ST_GeomFromText('POLYGON((0 0, 2 0.4, 4 0, 6 0.5, 8 0, 10 0.3, 10 6, 8 5.7, 6 6, 4 5.6, 2 6, 0 5.8, 0 0))')),
  ('Lake Bell',  ST_GeomFromText('POLYGON((0 0, 5 0.2, 10 0, 10 10, 5 9.8, 0 10, 0 0))'))
) t(lake_name, geom);

solution:
LOAD spatial;

SELECT lake_name,
       ROUND(ST_Area(geom), 2) AS area_before,
       ROUND(ST_Area(ST_Simplify(geom, 1.0)), 2) AS area_after
FROM lake_shores
ORDER BY lake_name;
